module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);
    function $mux4to1;
        input [3:0] in;
        input [1:0] sel;
        integer i;
        begin
            reg out_reg;
            for (i = 0; i < 4; i = i + 1) begin
                case (sel)
                    2'd0: out_reg = in[0];
                    2'd1: out_reg = in[1];
                    2'd2: out_reg = in[2];
                    2'd3: out_reg = in[3];
                    default: out_reg = in[0];
                endcase
            end
        end
    endfunction

    assign out = $mux4to1(in, sel);

endmodule

module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);
    wire [3:0] D;
    assign D[0] = in[0] & (sel == 2'b00);
    assign D[1] = in[1] & (sel == 2'b01);
    assign D[2] = in[2] & (sel == 2'b10);
    assign D[3] = in[3] & (sel == 2'b11);

    assign out = D[0] | D[1] | D[2] | D[3];
endmodule

module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);
    wire [3:0] not_sel;
    wire n10, n11, n12, n13;
    wire term0, term1, term2, term3;
    wire [3:0] and_out;

    // Invert select signals
    not (not_sel[1], sel[1]);
    not (not_sel[0], sel[0]);

    // Generate terms for each input
    and (term0, in[0], not_sel[1], not_sel[0]);
    and (term1, in[1], not_sel[1], sel[0]);
    and (term2, in[2], sel[1], not_sel[0]);
    and (term3, in[3], sel[1], sel[0]);

    // Combine terms into an OR gate
    or (and_out, term0, term1, term2, term3);

    // Buffer the final output
    buf (out, and_out);
endmodule

module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);
    wire [3:0] in_gated;
    wire enable0, enable1, enable2, enable3;

    // Gate each input with the inverters using AND gates
    and (in_gated[0], in[0], sel[1], ~sel[0]);
    and (in_gated[1], in[1], sel[1], ~sel[0]);
    and (in_gated[2], in[2], sel[0], ~sel[1]);
    and (in_gated[3], in[3], sel[0], ~sel[1]);

    // Invert the enable signals (assuming they are part of the problem's interface)
    wire en0, en1, en2, en3;
    not (en0, in_gated[0]);
    not (en1, in_gated[1]);
    not (en2, in_gated[2]);
    not (en3, in_gated[3]);

    // Combine the inverted enables using OR gates
    or (out, en0, en1, en2, en3);
endmodule

module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);
    wire not_sel1, not_sel0;
    wire en0, en1, en2, en3;
    wire term0, term1, term2, term3;
    wire or0, or1;

    not #1 (not_sel1, sel[1]);
    not #1 (not_sel0, sel[0]);

    and #1 (en0, not_sel1, not_sel0);
    and #1 (en1, not_sel1, sel[0]);
    and #1 (en2, sel[1], not_sel0);
    and #1 (en3, sel[1], sel[0]);

    and #1 (term0, in[0], en0);
    and #1 (term1, in[1], en1);
    and #1 (term2, in[2], en2);
    and #1 (term3, in[3], en3);

    or #1 (or0, term0, term1);
    or #1 (or1, term2, term3);
    or #1 (out, or0, or1);
endmodule

