module fsm_3state (
    input clk, reset,
    output [1:0] state
);
    localparam [1:0] s0 = 2'b00,
                     s1 = 2'b01,
                     s2 = 2'b10,
                     s3 = 2'b11;

    reg [1:0] current_state, next_state;

    always @(posedge clk) begin
        if (reset)
            current_state <= s0;
        else
            current_state <= next_state;
    end

    always @(*) begin
        case (current_state)
            s0: next_state = s1;
            s1: next_state = s2;
            s2: next_state = s3;
            s3: next_state = s0;
            default: next_state = s0;
        endcase
    end

    assign state = current_state;

endmodule

