module traffic_light (
    input clk, reset,
    output [2:0] light
);

reg [2:0] current_state, next_state;

// State transitions (cyclic)
always @(*) begin
    next_state = {current_state[1:0], current_state[2]};
end

// Output logic (combinational)
assign light = current_state;

// Sequential logic with synchronous reset
always @(posedge clk) begin
    if (reset)
        current_state <= 3'b111; // S0: All lights on
    else
        current_state <= next_state;
end

endmodule

module traffic_light (
    input clk, reset,
    output [2:0] light
);

    reg [1:0] current_state;
    parameter S0 = 2'b00,
              S1 = 2'b01,
              S2 = 2'b10,
              S3 = 2'b11;

    reg [1:0] next_state;
    reg [2:0] counter;

    // State transition and counter logic
    always @(posedge clk) begin
        if (reset) begin
            current_state <= S0;
            counter <= 3'd0;
        end else begin
            case (current_state)
                S0: counter <= (counter == 3'd5) ? S1 : counter + 1;
                S1: counter <= (counter == 3'd3) ? S2 : counter + 1;
                S2: counter <= (counter == 3'd5) ? S3 : counter + 1;
                S3: counter <= (counter == 3'd3) ? S0 : counter + 1;
                default: counter <= 3'd0;
            endcase
        end
    end

    // Next state logic
    always @(*) begin
        case (current_state)
            S0: next_state = (counter == 3'd5) ? S1 : S0;
            S1: next_state = (counter == 3'd3) ? S2 : S1;
            S2: next_state = (counter == 3'd5) ? S3 : S2;
            S3: next_state = (counter == 3'd3) ? S0 : S3;
            default: next_state = S0;
        endcase
    end

    // Output logic
    assign light = (current_state == S0) ? 3'b001 :
                  (current_state == S1) ? 3'b010 :
                  (current_state == S2) ? 3'b010 :
                  (current_state == S3) ? 3'b001 : 3'b001;

endmodule

module traffic_light (
    input clk, reset,
    output [2:0] light
);

    // State definitions
    localparam [1:0] RED   = 2'b00,
                     YELLOW = 2'b01,
                     GREEN  = 2'b10;

    reg [1:0] current_state, next_state;

    // State register with synchronous reset
    always @(posedge clk) begin
        if (reset)
            current_state <= RED;
        else
            current_state <= next_state;
    end

    // Next state logic (cycles through states)
    always @(*) begin
        case (current_state)
            RED:   next_state = YELLOW;
            YELLOW next_state = GREEN;
            GREEN  next_state = RED;
            default: next_state = RED;
        endcase
    end

    // Output logic based on current state
    assign light = (current_state == RED)   ? 3'b001 :
                  (current_state == YELLOW) ? 3'b010 :
                  (current_state == GREEN)  ? 3'b100 : 3'b001;

endmodule

