            S3: next_state = S4;
            S4: next_state = S5;
            S5: next_state = S0;
            default: next_state = S0;
        endcase
    end

    assign light = light_reg;

endmodule

module elevator_controller (
    input clk, reset,
    input up_request, down_request,
    output [1:0] state
);

// Define states
localparam S0 = 2'b00;
localparam S1 = 2'b01;
localparam S2 = 2'b10;
localparam S3 = 2'b11;

reg [1:0] current_state, next_state;

// State register
always @(posedge clk) begin
    if (reset)
        current_state <= S0;
    else
        current_state <= next_state;
end

// Next state logic
always @(*) begin
    case (current_state)
        S0: begin
            if (up_request)
                next_state = S1;
            else if (down_request)
                next_state = S2;
            else
                next_state = S0;
        end
        S1: begin
            if (up_request)
                next_state = S1;
            else
                next_state = S0;
        end
        S2: begin
            if (down_request)
                next_state = S2;
            else
                next_state = S0;
        end
        default: next_state = S0;
    endcase
end

// Output current state
assign state = current_state;

endmodule

