module elevator_controller (
    input clk, reset,
    input up_request, down_request,
    output [1:0] state
);

    // State definitions
    localparam [1:0] IDLE   = 2'b00,
                     Mv_to_1 = 2'b01,
                     Mv_to_2 = 2'b10,
                     Mv_to_3 = 2'b11;

    reg [1:0] current_state, next_state;
    reg [2:0] counter;

    // State register and counter logic
    always @(posedge clk) begin
        if (reset) begin
            current_state <= IDLE;
            counter <= 0;
        end else begin
            current_state <= next_state;
            // Counter logic for wait cycles
            if (current_state != next_state)
                counter <= 0;
            else if (counter < 3'd7)
                counter <= counter + 1;
            else
                counter <= 7;
        end
    end

    // Next state logic
    always @(*) begin
        next_state = current_state;
        case (current_state)
            IDLE: begin
                if (up_request)
                    next_state = Mv_to_1;
                else if (down_request)
                    next_state = Mv_to_2;
            end
            Mv_to_1: begin
                if (counter == 7) begin
                    case (1'b1)
                        up_request: next_state = Mv_to_1;
                        down_request: next_state = IDLE;
                    endcase
                end
            end
            Mv_to_2: begin
                if (counter == 7) begin
                    case (1'b1)
                        up_request: next_state = Mv_to_1;
                        down_request: next_state = IDLE;
                    endcase
                end
            end
            Mv_to_3: begin
                if (counter == 7) begin
                    case (1'b1)
                        up_request: next_state = Mv_to_1;
                        down_request: next_state = IDLE;
                    endcase
                end
            end
            default: next_state = IDLE;
        endcase
    end

    assign state = current_state;

endmodule

