    wire [7:0] sum_total;

    // Compute partial products
    assign pp0 = {4'b0, (a & {4{b[0]}})} << 0;
    assign pp1 = {4'b0, (a & {4{b[1]}})} << 1;
    assign pp2 = {4'b0, (a & {4{b[2]}})} << 2;
    assign pp3 = {4'b0, (a & {4{b[3]}})} << 3;

    // Sum the partial products
    assign sum_total = pp0 + pp1 + pp2 + pp3;

    // Invert the sum using AND gates
    assign out = ~sum_total;

    // Compute individual sum bits with carry
    assign {carry0, s0} = pp0[0] + pp1[0] + pp2[0] + pp3[0];
    assign {carry1, s1} = pp0[1] + pp1[1] + pp2[1] + pp3[1];
    assign {carry2, s2} = pp0[2] + pp1[2] + pp2[2] + pp3[2];
    assign {carry3, s3} = pp0[3] + pp1[3] + pp2[3] + pp3[3];

