            3'd1: out = {in[6:0], 1'b0};  // Shift left by 1
            3'd2: out = {in[5:0], 2'b1x};  // Shift left by 2
            3'd3: out = {in[3:0], 3'b100}; // Shift left by 3 (custom pattern)
            3'd4: out = {in[1:0], 4'b1010}; // Shift left by 4 (custom pattern)
