    and n8 (term1_lt3, n_a3_and_b3, eq_bit[3]);

    // Combine terms using AND gates
    and a_gt (gt, gt[3], gt[2], gt[1], gt[0]);
    and a_lt (lt, term1_lt3, term1_lt2, term1_lt1, term1_lt0);
    and a_eq (eq, eq_bit[3], eq_bit[2], eq_bit[1], eq_bit[0]);

    // Apply specified delay
    specify
        (gt => gt) = (DELAY > 0) ? DELAY : 0;
        (eq => eq) = (DELAY > 0) ? DELAY : 0;
        (lt => lt) = (DELAY > 0) ? DELAY : 0;
    endspecify
endmodule

module comparator_4bit(input [3:0] a, input [3:0] b, output gt, eq, lt);

wire [3:0] eq_bit;

assign eq_bit[3] = a[3] & b[3];
assign eq_bit[2] = a[2] & b[2];
assign eq_bit[1] = a[1] & b[1];
assign eq_bit[0] = a[0] & b[0];

wire eq_bit_and;
assign and(eq_bit_and, &eq_bit);

assign eq = eq_bit_and;

wire [3:0] a_g, b_g;

genvar i;
generate
  for (i=3; i>=0; i=i+1) begin: gen_ora
    if (i == 3) begin
      assign or(a_g[i], a[i], eq_bit[3]);
      or(b_g[i], b[i], eq_bit[3]);
    end else begin
      assign or(a_g[i], a[i], eq_bit[i+1]);
      assign or(b_g[i], b[i], eq_bit[i+1]);
    end
  end
endgenerate

wire a_gt, b_gt;

assign and(a_gt, |a_g);
assign and(b_gt, |b_g);
assign gt = a_gt & b_gt;

assign and(lt, a_gt, b_gt);

endmodule

module comparator_4bit(input [3:0] a, input [3:0] b, output gt, eq, lt);

    wire [3:0] a_nonblock;
    wire [3:0] b_nonblock;
    wire [3:0] gt_temp;
    wire [3:0] eq_temp;
    wire [3:0] lt_temp;
    integer i;

    always @* begin
        // Assign a_nonblock with 1ns rise delay
        #1 a_nonblock = a;
        // Assign b_nonblock with 1ns rise delay
        #1 b_nonblock = b;

        // Compute gt_temp and its delay
        genvar j;
        generate
            for (j=0; j<4; j=j+1) begin: GT
                assign #(2,1,1) gt_temp[j] = a_nonblock[j] & ~b_nonblock[j];
            end
        endgenerate

        // Compute eq_temp and its delay
        generate
            for (j=0; j<4; j=j+1) begin: EQ
                assign #(2,1,1) eq_temp[j] = a_nonblock[j] & b_nonblock[j];
            end
        endgenerate

        // Compute lt_temp and its delay
        generate
            for (j=0; j<4; j=j+1) begin: LT
                assign #(2,1,1) lt_temp[j] = ~a_nonblock[j] & b_nonblock[j];
            end
        endgenerate
    end

    assign gt = &gt_temp;
    assign eq = &eq_temp;
    assign lt = &lt_temp;

endmodule

