module gray_counter8(
    input wire clk,
    input wire rst,
    output wire [7:0] count
);

reg [7:0] binary;
reg [7:0] next_binary;

// Combinational logic for next state
always @* begin
    if (rst) begin
        next_binary = 8'd1; // Predefined state for reset (active high)
    end else begin
        next_binary = binary + 8'd2; // Increment by 2 in binary domain
    end
end

// Sequential logic for binary counter
always @(posedge clk) begin
    binary <= next_binary;
end

// Combinational logic for Gray code conversion
assign count = (binary ^ (binary >> 1)) ^ 8'd1;

endmodule

module gray_counter8(
    input wire clk,
    input wire rst,
    output wire [7:0] count
);

    reg [2:0] current_state;
    wire [2:0] next_state;
    wire [2:0] next_gray;
    wire [2:0] next_binary;

    // Combinational logic for next_state
    always @(*) begin
        case (current_state)
            3'b000: next_state = 3'b001;
            3'b001: next_state = 3'b011;
            3'b011: next_state = 3'b010;
            3'b010: next_state = 3'b110;
            3'b110: next_state = 3'b111;
            3'b111: next_state = 3'b101;
            3'b101: next_state = 3'b100;
            3'b100: next_state = 3'b000;
            default: next_state = 3'b000;
        endcase
    end

    // Combinational logic for next_gray
    always @(*) begin
        case (next_state)
            3'b000: next_gray = 3'b000;
            3'b001: next_gray = 3'b001;
            3'b011: next_gray = 3'b011;
            3'b010: next_gray = 3'b010;
            3'b110: next_gray = 3'b110;
            3'b111: next_gray = 3'b111;
            3'b101: next_gray = 3'b101;
            3'b100: next_gray = 3'b100;
            default: next_gray = 3'b000;
        endcase
    end

    // Combinational logic for next_binary
    always @(*) begin
        case (next_gray)
            3'b000: next_binary = 3'b000;
            3'b001: next_binary = 3'b001;
            3'b011: next_binary = 3'b010;
            3'b010: next_binary = 3'b011;
            3'b110: next_binary = 3'b100;
            3'b111: next_binary = 3'b101;
            3'b101: next_binary = 3'b110;
            3'b100: next_binary = 3'b111;
            default: next_binary = 3'b000;
        endcase
    end

    // Sequential logic for current_state
    always @(posedge clk) begin
        if (rst)
            current_state <= 3'b000;
        else
            current_state <= next_state;
    end

    // Output assignment
    assign count = {next_binary[2], next_binary[1], next_binary[0]};

endmodule

