// Binary counter with synchronous reset
always @(posedge clk) begin
    if (rst) begin
        binary_counter <= 8'b0;
    end else begin
        binary_counter <= binary_counter + 1;
    end
end

// Convert binary count to Gray code (active-low reset has priority)
assign count = (~rst) ? (binary_counter ^ (binary_counter >> 1)) : 8'bzzzzzzzz;

endmodule

module gray_counter8(
    input wire clk,
    input wire rst,
    output wire [7:0] count
);

    wire [7:0] binary;

    // B7 = binary[7]
    assign binary[7] = rst ? 1'b1 : 1'b0;

    // B6 = binary[6]
    assign binary[6] = binary[7] ^ (binary[7] & binary[6]);

    // B5 = binary[5]
    assign binary[5] = binary[6] ^ (binary[6] & binary[5]);

    // B4 = binary[4]
    assign binary[4] = binary[5] ^ (binary[5] & binary[4]);

    // B3 = binary[3]
    assign binary[3] = binary[4] ^ (binary[4] & binary[3]);

    // B2 = binary[2]
    assign binary[2] = binary[3] ^ (binary[3] & binary[2]);

    // B1 = binary[1]
    assign binary[1] = binary[2] ^ (binary[2] & binary[1]);

    // B0 = binary[0]
    assign binary[0] = binary[1] ^ (binary[1] & binary[0]);

    // Convert binary to gray code
    assign count = (binary ^ (binary >> 1)) ^ 8'hFF;

endmodule

