    assign D2_next[3] = q[0];
    assign D2_next[2] = 1'b0;
    assign D2_next[1] = feedback;
    assign D2_next[0] = 1'b0;

    // D3: Next state is {feedback, q[2:1]}
    wire [3:0] D3_next;
    assign D3_next[3] = feedback;
    assign D3_next[2] = q[2];
    assign D3_next[1] = q[1];
    assign D3_next[0] = 1'b0;

    // Update flip-flops with asynchronous reset
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            q[0] <= 1'b0;
            q[1] <= 1'b0;
            q[2] <= 1'b0;
            q[3] <= 1'b0;
        end else begin
            q[0] <= D0_next[0];
            q[1] <= D0_next[1];
            q[2] <= D0_next[2];
