  assign D[0] = resetn | r[0];

  // Generate D[1] using resetn, previous D bits, and r[1]
  assign D[1] = resetn | D[0] | r[1];

  // Generate D[2] using resetn, previous D bits, and r[2]
  assign D[2] = resetn | D[1] | r[2];

  // Generate D[3] using resetn, previous D bits, and r[0]
  assign D[3] = resetn | D[2] | r[0];

  // Generate D[4] using resetn, previous D bits, and r[1]
  assign D[4] = resetn | D[3] | r[1];

  // Generate D[5] using resetn, previous D bits, and r[2]
  assign D[5] = resetn | D[4] | r[2];

  // Generate D[6] using resetn, previous D bits, and r[0]
  assign D[6] = resetn | D[5] | r[0];

  // Generate D[7] using resetn, previous D bits, and r[1]
  assign D[7] = resetn | D[6] | r[1];

  // Update internal register A on clock edge or reset
  always @(posedge clk or negedge resetn) begin
    if (!resetn) begin
      A <= 8'h0;
    end else begin
      A <= {D[7], A[7:1]}; // Compute new A value, then assign to A
    end
  end

  // Output the LSB of A when resetn is active
  assign g = resetn ? {A[0], 2'b00} : 3'b000;

