module TopModule (
  input clk,
  input resetn,
  input  [2:0] r,
  output [2:0] g
);

  reg [1:0] current_state;
  reg [1:0] next_state;
  reg [1:0] next_reg;

  // State transition on rising edge of clk or falling edge of resetn
  always @(posedge clk or negedge resetn) begin
    if (!resetn)
      current_state <= 2'b00;
    else
      current_state <= next_state;
  end

  // Next state and register logic on falling edge of clk or resetn
  always @(negedge clk or negedge resetn) begin
    if (!resetn) begin
      next_state <= 2'b00;
      next_reg <= 2'b00;
    end else begin
      next_state <= current_state;
      case (current_state)
        2'b00: begin
          // Example: Update register in state 00
          if (r[0]) next_reg <= r[1:0];
        end
        2'b01: begin
          // Example: Update register in state 01
          if (r[1]) next_reg <= r[1:0];
        end
        default: ; // Handle other states or use r's other bits
      endcase
    end
  end

  // Output logic for green signal
  assign g = (next_state == 2'b00) ? 3'b001 :
             (next_state == 2'b01) ? 3'b010 :
             3'b100;

endmodule

