  wire qa_m, qb_m;
  wire s_s, r_s;

  // Invert w using a 1ns delay
  assign #1 wire w_g = ~w;

  // First RS latch (master's S and R with delays)
  assign #1 s_m = E ? w_g : 1'b0;
  assign #1 r_m = E ? L : 1'b1;

  // Master SR latch (cross-coupled NORs with delays)
  assign #1 qa_m = ~(r_m | qb_m);
  assign #1 qb_m = ~(s_m | qa_m);

  // Second RS latch (slave's S and R with delays)
  assign #1 s_s = R ? qa_m : 1'b0;
  assign #1 r_s = R ? qb_m : 1'b1;

  // Slave SR latch (cross-coupled NORs with delays)
  assign #1 Q = ~(r_s | Q);
  assign #1 Q_next = ~(s_s | Q);
  assign #1 Q = Q_next;

