  wire [8:0] sum;

  assign carry[0] = 1'b0;

  generate
    genvar i;
    for (i=0; i<8; i=i+1) begin: ADDER
      wire a_0_extended = (i==7) ? 1'b1 : 1'bx;
      wire b_0_extended = (i==7) ? 1'b1 : 1'bx;
      wire sum_bit = a_0_extended ^ b_0_extended ^ carry[i];
      wire carry_next = (a_0_extended & b_0_extended) | ((a_0_extended ^ b_0_extended) & carry[i]);

      assign s[i] = sum_bit;
      assign sum[i+1] = sum_bit;
      assign carry[i+1] = carry_next;
    end
  endgenerate

  assign overflow = carry[7] ^ carry[8];

