      nand(carry[i+1], xor_ab_ab_ab, carry[i]);
      nand(s[i], xor_ab_ab_ab, carry[i]);

      // Compute a_ab AND b_ab for carry calculation
      nand(and_a_ab_ab, a_ab, b_ab);
      nand(carry_ab_or_ab, and_a_ab_ab, and_a_ab_ab);
      nand(carry_ab_and_ab, carry_ab_or_ab, carry_ab_or_ab);

      // Compute sum_ab OR carry_ab for carry_out
      nand(carry_xor_ab_or_ab, carry_ab_and_ab, carry_ab_or_ab);
      nand(carry_or_ab_or_ab, carry_xor_ab_or_ab, carry_xor_ab_or_ab);
      nand(carry_out, carry_or_ab_or_ab, carry_or_ab_or_ab);
