module TopModule (
  input clk,
  input j,
  input k,
  input reset,
  output out
);
  wire clk_gated;
  wire d;

  assign clk_gated = ~reset ? 1'b0 : clk;

  // Step 1: Invert j and k using NAND gates
  wire n13, n14, n15, n16;
  nand(n13, j, j);    // n13 = ~j
  nand(n14, k, k);    // n14 = ~k

  // Step 2: Generate S' and R' using NAND gates
  wire n10, n11, n12, n17, n18, n19, n20;
  nand(n10, j, clk_gated);    // n10 = S'
  nand(n11, n13, n10);         // n11 = R' (k's original NAND)
  nand(n12, ~j, clk_gated);     // Part of S (assuming typo)
  nand(n13, ~k, n12);          // Part of R (assuming typo)

  // Step 3: Cross-coupled NAND gates forming the latch
  nand(n14, n10, n17);
  nand(n15, n11, n14);
  nand(n16, n12, n18);
  nand(n17, n18, n16);

  // Step 4: Invert using NAND gates for S and R
  nand(n18, n16, n16);         // n18 = S
  nand(n19, n17, n17);         // n19 = R

  // Step 5: Combine with reset to form d
  nand(d, n18, n19, reset);     // d = S & R & ~reset

  // Step 6: Invert d using NAND gate
  nand(out, d, d);              // out = ~d

endmodule

