module TopModule (
  input a,
  input b,
  output out_and,
  output out_or,
  output out_xor,
  output out_nand,
  output out_nor,
  output out_xnor,
  output out_anotb
);
  reg and_reg;
  reg or_reg;
  reg xor_reg;
  reg nand_reg;
  reg nor_reg;
  reg xnor_reg;
  reg anotb_reg;

  always @(*) begin
    // AND: a & b with 1ns rise, 2ns fall
    and_reg = a & b;
    specify
      if (a & b)  ( (a & b <= #1 and_reg) & (and_reg <= #2 (a & b)) );
    endspec

    // OR: a | b with 1ns rise, 2ns fall
    or_reg = a | b;
    specify
      if (a | b)  ( (a | b <= #1 or_reg) & (or_reg <= #2 (a | b)) );
    endspec

    // XOR: a ^ b with 1ns rise, 2ns fall
    xor_reg = a ^ b;
    specify
      if (a ^ b)  ( (a ^ b <= #1 xor_reg) & (xor_reg <= #2 (a ^ b)) );
    endspec

    // NAND: ~ (a & b) with 1ns rise, 2ns fall
    nand_reg = ~(a & b);
    specify
      if (a & b)  ( (a & b <= #1 nand_reg) & (nand_reg <= #2 (a & b)) );
    endspec

    // NOR: ~ (a | b) with 1ns rise, 2ns fall
    nor_reg = ~(a | b);
    specify
      if (a | b)  ( (a | b <= #1 nor_reg) & (nor_reg <= #2 (a | b)) );
    endspec

    // XNOR: ~ (a ^ b) with 1ns rise, 2ns fall
    xnor_reg = ~(a ^ b);
    specify
      if (a ^ b)  ( (a ^ b <= #1 xnor_reg) & (xnor_reg <= #2 (a ^ b)) );
    endspec

    // Buffer: Assign output based on a with 1ns rise, 2ns fall
    anotb_reg = a;
    specify
      if (a)  ( (a <= #1 anotb_reg) & (anotb_reg <= #2 a) );
    endspec
  end

  assign out_and = and_reg;
  assign out_or = or_reg;
  assign out_xor = xor_reg;
  assign out_nand = nand_reg;
  assign out_nor = nor_reg;
  assign out_xnor = xnor_reg;
  assign out_anotb = anotb_reg;

