  wire [3:0] or_out;
  wire [3:0] xor_out;

  assign #100; // 100 time unit delay

  genvar i;
  generate
    for (i=0; i<4; i=i+1) begin: AND_OR_XOR
      // AND gate with rise delay 10 and fall delay 20
      and #(10, 20) and_gate (and_out[i], in[i], in[i+1]);
      // OR gate with rise delay 5 and fall delay 15
      or #(5, 15) or_gate (or_out[i], and_out[i], in[i+1]);
      // XOR gate with rise delay 1 and fall delay 3
      xor #(1, 3) xor_gate (xor_out[i], or_out[i], in[i+1]);
