module TopModule (
  input a,
  input b,
  output sum,
  output cout
);
  wire a_buffer;
  wire [1:0] t1;
  wire b_buffer;
  wire [1:0] t2;
  wire sum_wire;
  wire [1:0] t3;

  // Invert a using a gate
  assign #1 a_buffer = ~a;

  // Buffer b using a gate
  assign #1 b_buffer = b;

  // Compute a XOR b using NAND and NOT gates
  wire nand_ab = a_buffer ~& b_buffer;
  wire not_a = a_buffer ~& a_buffer;
  wire not_nand = not_a ~& not_a;
  wire t1_part = not_a ~& b_buffer;
  wire t1_or = t1_part ~& t1_part;
  wire t2_part = a_buffer ~& not_nand;
  wire t2_or = t2_part ~& t2_part;
  assign #1 t1 = {t1_or, t2_or};

  // Compute borrow using NAND and NOT gates
  wire not_a_borrow = a_buffer ~& a_buffer;
  wire not_b_buffer = b_buffer ~& b_buffer;
  wire t2_part_borrow = not_a_borrow ~& not_b_buffer;
  wire t2_or_borrow = t2_part_borrow ~& t2_part_borrow;
  assign #1 t2 = {t2_or_borrow, t2_or_borrow};

  // Compute sum using XOR of t1 and t2
  wire nand_sum = t1[1] ~& t2[1];
  wire not_t1 = t1[1] ~& t1[1];
  wire not_t2 = t2[1] ~& t2[1];
  wire t3_part = not_t1 ~& not_t2;
  wire t3_or = t3_part ~& t3_part;
  assign #1 t3 = {t3_or, t3_or};

  // Assign sum and cout
  assign sum = t3[1];
  assign cout = t3[0];

endmodule

