module TopModule (
  input d,
  input ena,
  output logic q
);
  parameter [4:0] INIT = 5'b0,
                B1 = "x",
                C1 = 100,
                C2 = 100;

  reg [4:0] current_state, next_state;
  wire g, h;
  reg g_reg, h_reg;

  // Next state combinational logic
  always @(*) begin
    case (current_state)
      INIT: next_state = B1;
      B1: next_state = {d, d} & {3{ena}};
      default: next_state = B1;
    endcase
  end

  // State register with reset to INIT
  always @(posedge ena) begin
    if (current_state != INIT)
      current_state <= INIT;
    else
      current_state <= next_state;
  end

  // Next output combinational logic
  always @(*) begin
    case (current_state)
      INIT: {g_reg, h_reg} = 2'b10;
      B1: {g_reg, h_reg} = {2{d}};
      default: {g_reg, h_reg} = 2'b10;
    endcase
  end

  // Output register with reset to INIT
  always @(posedge ena) begin
    if (current_state != INIT)
      q <= 1'b0;
    else
      q <= g_reg;
  end

  // Next output combinational logic for C1
  always @(*) begin
    case (current_state)
      INIT: begin
        if (d)
          next_c1 = d / C1;
        else
          next_c1 = 100;
      end
      B1: begin
        if (d)
          next_c1 = (d * 10) / C1;
        else
          next_c1 = 100;
      end
      default: next_c1 = 100;
    endcase
  end

  reg c1_reg;
  always @(posedge ena) begin
    if (current_state != INIT)
      c1_reg <= 100;
    else
      c1_reg <= next_c1;
  end

  // Next output combinational logic for C2
  reg [12:0] next_c2;
  always @(*) begin
    case (current_state)
      INIT: next_c2 = d ? 10'd1 : 10'd0;
      B1: next_c2 = 10'd10;
      default: next_c2 = 10'd0;
    endcase
  end

  reg [12:0] c2_reg;
  always @(posedge ena) begin
    if (current_state != INIT)
      c2_reg <= 13'd0;
    else
      c2_reg <= next_c2;
  end

  // Output assignments
  assign #1 c1 = c1_reg;
  assign #1 c2 = c2_reg;

endmodule

module TopModule (
