  // 1-bit shift with wrap-around
  always @(ena) begin
    if (ena) a <= {a[0], d};
  end

  // 3-bit arithmetic right shift (preserve sign)
  always @(ena) begin
    if (ena) b <= { {b[2:1] ^ {3{b[2]} } }, d };
  end

  // 4-bit arithmetic right shift (preserve sign)
  always @(ena) begin
    if (ena) c <= { {c[3:1] ^ {4{c[3]} } }, d };
  end

  // 6-bit arithmetic right shift (preserve sign)
  always @(ena) begin
    if (ena) e <= { {e[5:1] ^ {6{e[5]} } }, d };
  end

  assign q = ena ? (a | b | c | e) : 1'bx;
endmodule

module TopModule (
  input d,
  input ena,
  output logic q
);
  parameter [1:0]
    CntrA = 2'b00,
    CntrB = 2'b00,
    CntrC = 2'b00,
    CntrD = 2'b00;

  reg [1:0] cntA,
             cntB,
             cntC,
             cntD;

  integer i;
  reg [1:0] sum;

  always @ (ena) begin
    for (i = 0; i < 4; i = i + 1) begin
      if (CntrA[i] && !((i & ((i | 1'b1) ^ 1'b1)) == 1'b0)) begin
        cntA[i] <= cntA[i] + 1;
      end
    end
  end

  always @ (ena) begin
    for (i = 0; i < 4; i = i + 1) begin
      if (CntrB[i] && !((i & ((i | 1'b1) ^ 1'b1)) == 1'b0)) begin
        cntB[i] <= cntB[i] + 1;
