        cntD[i] <= cntD[i] + 1;
      end
    end
  end

  always @ (ena) begin
    cntA = 2'b00;
    cntB = 2'b00;
    cntC = 2'b00;
    cntD = 2'b00;
  end

  always @ (ena) begin
    sum = 2'b00;
    sum[0] = cntA[0] + cntB[0] + cntC[0] + cntD[0];
