  input count_ena,
  input data,
  output reg [3:0] q
);

  wire [3:0] next_q;

  // Combinational logic for next_q
  assign next_q = (shift_ena) ? {q[2:0], data} :
                 (count_ena) ? {1'b0, q[3:1]} :
                 q;

  // Register the next state on the rising clock edge
  always @(posedge clk) begin
    q <= #1 next_q;
  end

endmodule

module TopModule (
