  input count_ena,
  input data,
  output reg [3:0] q
);

  always @(posedge clk) begin
    if (shift_ena) begin
      // Shift left and append data to LSB, handle wrap-around
      q <= {q[2:0], data};
    end
    else if (count_ena) begin
      // Decrement LSB and wrap around automatically
      q <= {q[3:1], (q[0] ^ 1'b1)};
    end
  end

endmodule

