module TopModule (
  input ring,
  input vibrate_mode,
  output ringer,
  output motor
);

  parameter [1:0] SILENCE = 2'b00,
                 RINGING = 2'b01,
                 VIBRATE = 2'b10,
                 RING_VIB = 2'b11;

  reg [1:0] state, next_state;

  always @(posedge ring) begin
    state <= next_state;
  end

  always @(*) begin
    case (state)
      SILENCE: next_state = RINGING;
      RINGING: next_state = VIBRATE;
      VIBRATE: next_state = RING_VIB;
      RING_VIB: next_state = SILENCE;
      default: next_state = SILENCE;
    endcase
  end

  always @(*) begin
    if (vibrate_mode) begin
      case (state)
        SILENCE: {motor, ringer} = 2'b00;
        RINGING: {motor, ringer} = 2'b11;
        VIBRATE: {motor, ringer} = 2'b11;
        RING_VIB: {motor, ringer} = 2'b11;
        default: {motor, ringer} = 2'b00;
      endcase
    end else begin
      {motor, ringer} = 2'b00;
    end
  end

  initial begin
    state = SILENCE;
  end

endmodule

