module TopModule (
  input ring,
  input vibrate_mode,
  output ringer,
  output motor
);

  parameter [1:0] Decible = 2'b11;
  parameter [1:0] Ring = 2'b11;
  parameter [1:0] Motor = 2'b11;
  parameter [1:0] Vibrate = 2'b11;

  reg [1:0] decible_reg;
  reg [1:0] ring_reg;
  reg [1:0] motor_reg;
  reg [1:0] vibrate_reg;

  integer i;
  reg [1:0] next_decible;
  reg [1:0] next_ring;
  reg [1:0] next_motor;
  reg [1:0] next_vibrate;

  always @(*) begin
    next_decible = decible_reg;
    next_ring = ring_reg;
    next_motor = motor_reg;
    next_vibrate = vibrate_reg;

    // Update decible based on Decible parameter (priority)
    if (Decible != 2'b11) begin
      next_decible = Decible;
    end else begin
      case (1'b1)
        ring: begin
          next_ring = Ring;
        end
        motor: begin
          next_motor = Motor;
        end
        vibrate: begin
          next_vibrate = Vibrate;
        end
        default: ;
      endcase
    end
  end

  always @(*) begin
    if (ring) begin
      next_decible = Decible;
      next_ring = Ring;
      next_motor = Motor;
      next_vibrate = Vibrate;
    end else if (vibrate_mode) begin
      next_decible = Vibrate;
      next_ring = Ring;
      next_motor = Motor;
      next_vibrate = Vibrate;
    end
  end

  always @(ring or vibrate_mode) begin
    decible_reg <= next_decible;
    ring_reg <= next_ring;
    motor_reg <= next_motor;
    vibrate_reg <= next_vibrate;
  end

  assign ringer = ring_reg[1];
  assign motor = motor_reg[1];

endmodule

