  always @(*) begin
    case (opcode)
      // R-type instructions (ADD, SUB, MUL, AND, OR, SLL)
      7'b0110011: begin
        rs1_addr = in[14:12];
        rs2_addr = in[11:9];
      end
      // I-type Arithmetic (ADDI)
      7'b0010011: begin
        rs1_addr = in[14:12];
        rs2_addr = 3'b0;
      end
      // I-type Load (LW)
      7'b0000011: begin
        rs1_addr = in[14:12];
        rs2_addr = 3'b0;
      end
      // S-type (Store)
      7'b0100011: begin
        rs1_addr = in[14:12];
        rs2_addr = in[11:9];
      end
      // SB-type (Branch)
      7'b1100011: begin
        rs1_addr = in[14:12];
        rs2_addr = in[11:9];
      end
      // U-type (LUI)
      7'b0110111: begin
        rs1_addr = in[14:12];
        rs2_addr = 3'b0;
      end
      // UJ-type (JAL)
      7'b1101111: begin
        rs1_addr = in[14:12];
        rs2_addr = 3'b0;
      end
      // JALR (UJ-type)
      7'b1100111: begin
        rs1_addr = in[14:12];
        rs2_addr = 3'b0;
      end
      // Default case (including others)
      default: begin
        rs1_addr = 3'b0;
        rs2_addr = 3'b0;
      end
    endcase
  end

  assign out = { {24{in[31]} } , rs1_addr, rs2_addr };

