  wire [5:0] opcode = in[6:0];
  reg [31:0] A, B;
  reg [31:0] next_A, next_B;
  integer i;

  always @(*) begin
    // Default assignments
    next_A = $random;
    next_B = $random;

    case (opcode)
      // Arithmetic operations (R-type)
      7'b0110011: begin
        next_A = in[30:25] ? (A + B) : (A - B);
        next_B = in[30:25] ? (B + A) : (B - A);
      end
      // Immediate operations (I-type)
      7'b0010011: begin
        case (in[14:12])
          3'b000: next_A = in[30:25] ? (A + $signed(in[31:20])) : (A << in[31:20]);
          3'b001: next_A = A - $signed(in[31:20]);
          default: next_A = A;
        endcase
      end
      // Load/Store (L-type)
      7'b0000011: begin
        next_A = { {20{in[31]}}, in[31:20] };
      end
      // Branch (B-type)
      7'b1100011: begin
        if ($signed(in[31:20]) >= 1'sd2) begin
          next_A = 32'bx;
          next_B = 32'bx;
        end
      end
      // JAL (J-type)
      7'b1101111: begin
        next_A = { {20{in[31]}}, in[31:20], in[20:10} };
      end
      // JALR (I-type)
      7'b1100111: begin
        next_A = { {20{in[31]}}, in[31:20], in[20:0] };
      end
      // LUI (U-type)
      7'b0111111: begin
        next_A = in[31:12];
      end
      // AUIPC (U-type)
      7'b0010111: begin
        next_A = { {20{in[31]}}, in[31], in[31:21], in[11:8] };
      end
      // System instruction (U-type)
      7'b1111111: begin
        case (in[14:12])
          3'b000: next_A = (A, B) => $st悸 (A, B);
          3'b001: next_A = (A, B) => $vtncs (A, B);
          3'b010: next_A = (A, B) => $vtpc (A, B);
          3'b011: next_A = (A, B) => $vtpc2 (A, B);
