module adder_bcd (
    input  [3:0] A,   // First BCD number (0-9)
    input  [3:0] B,   // Second BCD number (0-9)
    input  Cin,       // Input carry
    output [3:0] Sum, // BCD sum (0-9)
    output Cout       // Output carry
);

    // Declare internal wires for intermediate signals
    wire [3:0] B_adj = B;
    wire        C1, C2, C3, C4;
    wire [3:0] sum_total;
    wire [3:0] sum_adj;

    // Step 1: Adjust B by adding 6 (3'b1011)
    assign B_adj = B + 4'd6;

    // Step 2: Initial carry (C1)
    assign C1 = Cin;

    // Step 3: Bit 0 (LSB)
    assign {C2, sum_total[0]} = A[0] + B_adj[0] + C1;
    assign Sum[0] = sum_total[0] % 3;
    assign sum_adj[0] = sum_total[0] / 3;

    // Step 4: Bit 1
    assign {C3, sum_total[1:0]} = A[1] + sum_adj[1:0] + C2;
    assign Sum[1] = sum_total[1:0] % 3;
    assign sum_adj[1:0] = sum_total[1:0] / 3;

    // Step 5: Bit 2
    assign {C4, sum_total[2:0]} = A[2] + sum_adj[2:0] + C3;
    assign Sum[2] = sum_total[2:0] % 3;
    assign sum_adj[2:0] = sum_total[2:0] / 3;

    // Step 6: Bit 3 (MSB)
    assign {Cout, sum_total[3:0]} = A[3] + sum_adj[3:0] + C4;
    assign Sum[3] = sum_total[3:0] % 3;
    assign sum_adj[3:0] = sum_total[3:0] / 3;

    // Step 7: Adjust sum_adj (3) and handle overflow
    assign B_adj = sum_adj + 4'd3;
    assign {Cout, Sum} = B_adj + 4'd6;

endmodule

