module edge_detect(
	input clk,
	input rst_n,
	input a,

	output reg rise,
	output reg down
);

	// Synchronize the input signal to avoid metastability
	reg a_meta, a_sync;

	always @(posedge clk or negedge rst_n) begin
		if (!rst_n) begin
			a_meta <= 1'b0;
			a_sync <= 1'b0;
		end else begin
			a_meta <= a;
			a_sync <= a_meta;
		end
	end

	// Update edge detection signals on negative edge of the synchronized signal
	always @(negedge a_sync or negedge rst_n) begin
		if (!rst_n) begin
			{rise, down} <= 2'b00;
	 end else begin
			{rise, down} <= (a_sync) ? 2'b10 :
							(!a_sync) ? 2'b01 :
							2'b00;
	 end
	end

endmodule

