    always @(posedge clk) begin
        if (!rst_n) begin
            counter <= 5'd0;
        end else begin
            if (counter == NUM_DIV - 1) begin
                counter <= 5'd0;
            end else begin
                counter <= counter + 1;
            end
        end
    end

    // Output logic
    always @(posedge clk) begin
        if (!rst_n) begin
            clk_div <= 1'b0;
        end else begin
            clk_div <= (counter == ((NUM_DIV + 5'd1) >> 1)) ? 1'b1 : 1'b0;
        end
    end

