module LFSR (out, clk, rst);
  input clk, rst;
  output reg [3:0] out;

  wire feedback = out[3] ^ out[1]; // Feedback is XOR of bits 3 and 1 (0-based indices)

  always @(posedge clk) begin
    if (rst)
      out <= 4'b0000;
    else
      out <= {out[2:0], feedback}; // Shift left and insert feedback as LSB
  end
