  wire feedback = out[3] ^ out[1];
  wire [3:0] shifted = {out[2:0], 1'b0};
  wire [3:0] next_state = shifted ^ ( (rst) ? 4'hf : (4'h1 << feedback) );

  always @(posedge clk) begin
    out <= next_state;
  end

