    parameter [7:0] INIT = 8'b0;
    input [7:0] d;
    input [7:0] q;

    parameter [2:0]  
        S0 = 3'd0,
        S1 = 3'd1,
        S2 = 3'd2,
        S3 = 3'd3,
        S4 = 3'd4,
        S5 = 3'd5,
        S6 = 3'd6,
        S7 = 3'd7;

    reg [2:0] current_state, next_state;
    wire feedback;
    reg [7:0] next_q;

    // Combinational logic for next state and output
    always @* begin
        // Default assignments
        next_state = current_state;
        next_q = q;
        feedback = d;

        case (current_state)
            S0: next_q = INIT;
            S1: next_q[0] = feedback;
            S2: next_q[1:0] = {2{feedback}};
            S3: next_q[2:0] = {3{feedback}};
            S4: next_q[3:0] = {4{feedback}};
            S5: next_q[4:0] = {5{feedback}};
            S6: next_q[5:0] = {6{feedback}};
            S7: next_q[6:0] = {7{feedback}};
            default: next_state = S0;
        endcase
    end

    // Sequential logic for state and output
    always @(posedge clk) begin
        current_state <= next_state;
        q <= next_q;
    end

endmodule

