module right_shifter(clk, q,d);  

    input  clk;  
    input  d;  
    output [7:0] q;  

    reg [7:0] q_reg = 8'b00000000;  
    reg signed [7:0] delay_reg;  

    always @(posedge clk) begin  
        // Arithmetic right shift: preserve sign bit (MSB)  
        q_reg <= {q_reg[7], q_reg[7:1], d};  
        // Geometric right shift: fill LSB with 0  
        delay_reg <= {q_reg[7], q_reg[7:1], d} << 1;  
    end  

    assign q = q_reg;  

endmodule

module right_shifter(clk, q,d);  
    input  clk;  
