    output [7:0] q;  
    reg [7:0] q_reg;  
    reg q0_reg, q1_reg, q2_reg, q3_reg, q4_reg, q5_reg;

    wire [7:0] d_ext = {6'b0, d};

    always @(posedge clk) begin  
        q0_reg <= d_ext[0];
        q1_reg <= d_ext[1];
        q2_reg <= d_ext[0];
        q3_reg <= d_ext[1];
        q4_reg <= d_ext[0];
        q5_reg <= d_ext[1];
        q_reg  <= d_ext << 1;
    end
endmodule

module synchronizer(
	input 				clk_a	, 
	input 				clk_b	,   
	input 				arstn	,
	input				brstn   ,
	input		[3:0]	data_in	,
	input               data_en ,

	output reg  [3:0] 	dataout
);

	// Capture data_in and data_en in clk_a domain
	reg [3:0] data_reg;
	reg data_en_reg;
	always @(posedge clk_a or negedge arstn) begin
		if (!arstn) begin
			data_reg <= 4'b0;
			data_en_reg <= 1'b0;
		} else begin
			data_reg <= data_in;
			data_en_reg <= data_en;
		end
	end

	// Synchronize data_en to clk_b domain
	reg [1:0] sync_en_b;
	always @(posedge clk_b or negedge brstn) begin
		if (!brstn) begin
			sync_en_b <= 2'b0;
		end else begin
			sync_en_b <= {sync_en_b[0], data_en_reg};
		end
	end

	// Detect rising edge of synchronized enable signal
	reg sync_en_b_prev;
	always @(posedge clk_b or negedge brstn) begin
		if (!brstn) begin
			sync_en_b_prev <= 1'b0;
		end else begin
			sync_en_b_prev <= sync_en_b[1];
		end
	end

	wire data_en_b_rise = ~sync_en_b_prev & sync_en_b[1];

	// Update output data in clk_b domain
	always @(posedge clk_b or negedge brstn) begin
		if (!brstn) begin
			dataout <= 4'b0;
		end else begin
			if (data_en_b_rise) begin
				dataout <= data_reg;
			}
		end
	end

endmodule

module synchronizer(
	input 				clk_a	, 
