	always @(posedge clk_a or negedge arstn) begin
		if (!arstn) begin
			data_reg <= 4'b0;
			data_en_reg <= 1'b0;
			sync_en_ff1 <= 1'b0;
			sync_en_ff2 <= 1'b0;
		end else begin
			data_reg <= data_in;
			data_en_reg <= data_en;
			sync_en_ff1 <= data_en;
			sync_en_ff2 <= data_en_ff1;
		end
	end

	// clk_b domain logic
	reg [3:0] dataout_reg;
	reg en_meta, en_sync;
	reg en_prev;

	// Synchronize en_meta and en_sync
	always @(posedge clk_b or negedge brstn) begin
		if (!brstn) begin
			en_meta <= 1'b0;
			en_sync <= 1'b0;
			en_prev <= 1'b0;
		end else begin
			en_meta <= data_en_reg;
			en_sync <= en_meta;
			en_prev <= en_sync;
		end
	end

	// Edge detection and dataout update
	always @(posedge clk_b or negedge brstn) begin
		if (!brstn) begin
			dataout <= 4'b0;
	 end else begin
		 dataout <= (en_sync && !en_prev) ? dataout_reg : dataout;
	 end
 end

