module synchronizer(
	input 				clk_a	, 
	input 				clk_b	,   
	input 				arstn	,
	input				brstn   ,
	input		[3:0]	data_in	,
	input               data_en ,

	output reg  [3:0] 	dataout
);

	// Capture data_in on clk_a with asynchronous reset
	reg [3:0] data_reg;
	reg data_en_meta;
	reg data_en_sync;

	// Capture data_en on clk_b with asynchronous reset
	reg data_en_sync_meta, data_en_sync;
	reg data_en_prev;

	// clk_a domain signals
	always @(posedge clk_a or negedge arstn) begin
		if (!arstn) begin
			data_reg <= 4'b0;
			data_en_meta <= 1'b0;
			data_en_sync <= 1'b0;
			data_en_prev <= 1'b0;
		} else begin
			// Capture data_in on data_en
			if (data_en) begin
				data_reg <= data_in;
			end
			// Two-fphase synchronize data_en
			data_en_meta <= data_en;
			data_en_sync <= data_en_meta;
			// Edge detection for data_en_sync
			data_en_prev <= data_en_sync;
		}
	end

	// Detect rising edge of synchronized data_en
	wire data_en_rise = data_en_sync & ~data_en_prev;

	// clk_b domain signals
	reg [3:0] dataout_reg;
	reg data_en_sync_b_reg;

	always @(posedge clk_b or negedge brstn) begin
		if (!brstn) begin
			dataout_reg <= 4'b0;
			data_en_sync_b_reg <= 1'b0;
		} else begin
			// Two-phase synchronize data_en
			data_en_sync_b_reg <= data_en_sync;
			// Capture data when enabled
			if (data_en_rise) begin
				dataout_reg <= data_reg;
			}
		}
	end

	assign dataout = dataout_reg;

endmodule

module fsm(IN,MATCH,CLK,RST;
input IN,CLK,RST;
