localparam [1:0] s0, s1, s2, s3, s4;
reg [1:0] current_state, next_state;

// Combinational logic for next state and output
always @(*) begin
    // Default assignments
    next_state = current_state;
    MATCH = 1'b0;
    case (current_state)
        s0: begin
            if (IN) begin
                next_state = s1;
                MATCH = 1'b0;
            end else begin
                next_state = s0;
                MATCH = 1'b0;
            end
        end
        s1: begin
            if (IN) begin
                next_state = s2;
                MATCH = 1'b0;
            end else begin
                next_state = s0;
                MATCH = 1'b0;
            end
        end
        s2: begin
            if (IN) begin
                next_state = s3;
                MATCH = 1'b0;
            end else begin
                next_state = s0;
                MATCH = 1'b1;
            end
        end
        s3: begin
            if (IN) begin
                next_state = s4;
                MATCH = 1'b0;
            end else begin
                next_state = s0;
                MATCH = 1'b0;
            end
        end
        s4: begin
            if (IN) begin
                next_state = s4;
                MATCH = 1'b0;
            end else begin
                next_state = s0;
                MATCH = 1'b0;
            end
        end
        default: begin
            next_state = s0;
            MATCH = 1'b0;
        end
    endcase
end

// Sequential logic for state transition
always @(posedge CLK) begin
    if (RST) begin
        current_state <= s0;
    end else begin
        current_state <= next_state;
    end
end

endmodule

