    input rst_n,
    input [3:0] d,
    output valid_out,
    output dout
);

    reg [2:0] counter;
    reg [3:0] data_reg;

    wire feedback;

    assign feedback = data_reg[0];
    assign dout = feedback;
    assign valid_out = (counter == 3'd7);

    always @(posedge clk) begin
        if (!rst_n) begin
            data_reg <= 4'b0;
            counter <= 3'b0;
        end else begin
            if (counter < 3'd7) begin
                data_reg <= {feedback, d};
                counter <= counter + 3'd1;
            end
        end
    end

