    reg [3:0] next_shift_reg;
    reg [1:0] next_cnt;

    always @(*) begin
        next_shift_reg = shift_reg;
        next_cnt = cnt;
        if (rst_n) begin
            next_shift_reg = 4'b0;
            next_cnt = 2'b0;
        end else begin
            next_shift_reg = {shift_reg[0], shift_reg[3:1]};
            next_cnt = cnt + 1;
        end
    end

    always @(posedge clk) begin
        if (~rst_n) begin
            shift_reg <= 4'b0;
            cnt <= 2'b0;
        end else begin
            if (cnt < 2'b11) begin
                shift_reg <= next_shift_reg;
                cnt <= next_cnt;
            end
        end
    end

    assign valid_out = (cnt == 2'b11);
    assign dout = shift_reg[0];

