        if (~rst_n) begin
            shift_reg <= 16'd0;
            counter <= 4'd0;
        end else begin
            // Shift left by 1, append current d to LSB (LSB is new bit for next shift)
            shift_reg <= {shift_reg[14:0], d};
            counter <= counter + 1;
        end
    end

