     localparam S1    = 2'b01;
     localparam S11   = 2'b10;
     localparam S110  = 2'b11;

     reg [1:0] current_state, next_state;

     // State register
     always @(posedge clk) begin
        if (!rst_n)
            current_state <= S0;
        else
            current_state <= next_state;
     end

     // Next state logic
     always @(*) begin
        case (current_state)
            S0:    next_state = data_in ? S1 : S0;
            S1:    next_state = data_in ? S11 : S0;
            S11:   next_state = data_in ? S11 : S110;
            S110:  next_state = data_in ? S1 : S0;
            default: next_state = S0;
        endcase
     end

     // Output logic
     assign sequence_detected = (current_state == S110) && data_in;

endmodule
